        bool uPrintu = false;
        bool uPrintuses2 = false;
        bool uPrintuses3 = false;
 bool uPrintuses4 = false;

        private void xrTableCell28_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e)
        {
            if (Convert.ToInt32(GetCurrentColumnValue("SESION")) == 1)
            {
                xrTableCell28.Borders = DevExpress.XtraPrinting.BorderSide.Left;
                if (!uPrintu)
                {
                    xrTableCell28.Text = "Prodhimi i Energjise";
                    uPrintu = true;
                }
                else xrTableCell28.Text = "";

            }
            if ((Convert.ToInt32(GetCurrentColumnValue("SESION")) == 2))
            {
                xrTableCell28.Borders = DevExpress.XtraPrinting.BorderSide.Left;
                if (!uPrintuses2)
                {
                    xrTableCell28.Text = "Tregtimi i Energjise";
                    uPrintuses2 = true;
                    xrTableCell28.Borders = DevExpress.XtraPrinting.BorderSide.Top| DevExpress.XtraPrinting.BorderSide.Left;
                }
                else xrTableCell28.Text = "";


            }

            if ((Convert.ToInt32(GetCurrentColumnValue("SESION")) == 3))
            {
                xrTableCell28.Borders = DevExpress.XtraPrinting.BorderSide.Left;
                if (!uPrintuses3)
                {
                    xrTableCell28.Text = "Tarifat dhe cmimet";
                    uPrintuses3 = true;
                    xrTableCell28.Borders = DevExpress.XtraPrinting.BorderSide.Top| DevExpress.XtraPrinting.BorderSide.Left;
                }
                else xrTableCell28.Text = "";


            }


    if ((Convert.ToInt32(GetCurrentColumnValue("SESION")) == 4))
            {
                xrTableCell28.Borders = DevExpress.XtraPrinting.BorderSide.Left;
                if (!uPrintuses4)
                {
                    xrTableCell28.Text = "Treguesit e Punes";
                    uPrintuses4 = true;
                    xrTableCell28.Borders = DevExpress.XtraPrinting.BorderSide.Top| DevExpress.XtraPrinting.BorderSide.Left;
                }
                else xrTableCell28.Text = "";
            }

           }


private void xrTableCell21_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
if ((Convert.ToInt32(GetCurrentColumnValue("RRESHT")) == 1)||(Convert.ToInt32(GetCurrentColumnValue("RRESHT")) == 14)
||(Convert.ToInt32(GetCurrentColumnValue("RRESHT")) == 17)||(Convert.ToInt32(GetCurrentColumnValue("RRESHT")) == 20) ||(Convert.ToInt32(GetCurrentColumnValue("RRESHT")) == 37))
  xrTableCell21.Text = "";}
double vlerames;

private void xrTableCell22_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
double vleraaktuale;

if ((Convert.ToInt32(GetCurrentColumnValue("RRESHT")) == 1)||(Convert.ToInt32(GetCurrentColumnValue("RRESHT")) == 14)
||(Convert.ToInt32(GetCurrentColumnValue("RRESHT")) == 17)||(Convert.ToInt32(GetCurrentColumnValue("RRESHT")) == 20) ||(Convert.ToInt32(GetCurrentColumnValue("RRESHT")) == 37))
  xrTableCell22.Text = "";

if((Convert.ToInt32(GetCurrentColumnValue("RRESHT"))==38))
vlerames= Convert.ToInt32(xrTableCell22.Value);


if((Convert.ToInt32(GetCurrentColumnValue("RRESHT"))==39))
{
vleraaktuale= Convert.ToInt32(xrTableCell22.Value);
 double sasia = Convert.ToDouble(vleraaktuale) / Convert.ToDouble(vlerames);
                if(double.IsNaN(sasia) || double.IsInfinity(sasia))   
              xrTableCell22.Text = "0";
else 
	xrTableCell22.Text=sasia.ToString();


             int nr = 0;
            if (xrTableCell22.Text != "" || xrTableCell22.Text != "NaN")
            int.TryParse(xrTableCell22.Text, out nr);

}}


