        private string date;
private void Rap_PermbledheseRealizimevedheParashikimeve_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
xrPictureBox1.Image = AlphaWebReports.raporteUtil.MerrLogoNdermarrje(this.Extensions["ndermarrjeLogo"]);
var parametraRaporti = AlphaWebReports.raporteUtil.DeserializoParametraPerKonstruktorRaporti(this.Extensions["parametraRaporti"]);
 var parameters = AlphaWebReports.raporteUtil.DeserializoParametrat(this.Extensions["filtrat"]);  
var filterDtDok = parameters.Find(param => param.Emri == "filterDtDok");
           date  = filterDtDok.Vlera;

            int paramviti = Convert.ToInt32(parametraRaporti.KodiViti);
            int paramviti1 = 1 + paramviti;
            int paramviti2 = 2 + paramviti;
            int paramviti3 = 3 + paramviti;
            int paramviti4 = 4 + paramviti;
            int paramviti5 = 5 + paramviti;
            xrTableCell11.Text = "Programi i Vitit (I Ndryshuar) " + paramviti;
            xrTableCell12.Text = "Fakti " + date;
            xrTableCell13.Text = "I Pritshmi " + paramviti;
            xrTableCell9.Text = "Parashikimi i vitit " + paramviti1;
            xrTableCell14.Text = "Parashikimi i vitit " + paramviti2;
            xrTableCell15.Text = "Parashikimi i vitit " + paramviti3;
            xrTableCell16.Text = "Parashikimi i vitit " + paramviti4;
            xrTableCell18.Text = "Parashikimi i vitit " + paramviti5;

}
